// apps/web/src/reactionChips.ts
function groupReactions(m, meId) {
  const chips = [];
  if (m.reactionCounts) {
    const mineKey = m.myReaction ? emojiKey(m.myReaction) : null;
    for (const [emoji, count] of m.reactionCounts) {
      const key = emojiKey(emoji);
      chips.push({ key, emoji, count, mine: mineKey === key });
    }
    return chips;
  }
  const list = m.reactions ?? [];
  for (const r of list) {
    const key = emojiKey(r.emoji);
    const c = chips.find((x) => x.key === key);
    if (c) {
      c.count++;
      c.mine ||= r.userId === meId;
      c.who.push(r.userId);
    } else
      chips.push({ key, emoji: r.emoji, count: 1, mine: r.userId === meId, who: [r.userId] });
  }
  if (list.length >= 4)
    for (const c of chips)
      delete c.who;
  return chips;
}

