function arrivals(prev, list, live) {
  const seen = { list, keys: new Set(list.map((m) => m.key)), live };
  const fresh = [];
  if (prev && prev.live && live) {
    const first = list.findIndex((m) => prev.keys.has(m.key));
    if (first >= 0) {
      for (let i = first + 1;i < list.length; i++)
        if (!prev.keys.has(list[i].key))
          fresh.push(list[i].key);
    }
  }
  return { fresh, seen };
}

